class Aggregator:
    def __init__(self, expected, timeout, store):
        self.expected = expected  # 완료 조건: 메시지 개수
        self.timeout = timeout  # 완료 조건: 시간
        self.store = store  # 영속 저장소 {상관ID: (메시지목록, 시작시각)}

    def on_message(self, msg, now):
        cid = msg.correlation_id  # 관련 메시지 식별
        msgs, started = self.store.get(cid, ([], now))
        msgs.append(msg)
        if len(msgs) >= self.expected:  # 완료 → 하나로 결합
            self.store.delete(cid)
            return combine(msgs)  # 집계 전략 (예: 병합·합계)
        self.store.put(cid, (msgs, started))
        return None  # 미완료: 대기

    def on_tick(self, now):
        for cid, (msgs, started) in list(self.store.items()):
            if now - started >= self.timeout:  # 시간 초과
                self.store.delete(cid)
                publish(combine_partial(msgs)) # 부분 결과 처리
